ku]);$p->fill(['name'=>$name,'category_id'=>$cats[$cat]->id,'brand_id'=>$brands[$brand]->id,'short_description'=>'Reliable electronics product available from Prinx Electronics.','description'=>'Quality electronics product supplied by Prinx Electronics with clear product information and dependable support.','price'=>$price,'stock_quantity'=>$stock,'primary_image'=>$img,'mpn'=>$sku.'TZ','status'=>'active','condition'=>'new','track_stock'=>true,'merchant_sync_enabled'=>true,'shipping_price'=>0,'featured'=>true]);$p->deleted_at=null;$p->save();}$services=[['Phone Repair','Phone & Tablet Repair','/assets/repair.svg'],['Computer Repair & Upgrade','Computer Support','/assets/laptop.svg'],['Network Installation','Network & Installation','/assets/accessory.svg']];foreach($services as[$name,$cat,$img]){$s=Service::withTrashed()->firstOrNew(['slug'=>Str::slug($name)]);$s->fill(['name'=>$name,'category_id'=>$scats[$cat]->id,'short_description'=>'Professional electronics service from Prinx Electronics.','description'=>'Professional diagnostics, support and installation provided by the Prinx Electronics technical team.','image'=>$img,'status'=>'active','featured'=>true]);$s->deleted_at=null;$s->save();}}}
